CREATE OR REPLACE FUNCTION soldetotalclient (p_id_client IN NUMBER) RETURN NUMBER IS
  v_total NUMBER;
BEGIN
  SELECT NVL(SUM(solde), 0) INTO v_total FROM compte WHERE id_client = p_id_client;
  RETURN v_total;
END;
/

CREATE OR REPLACE PROCEDURE effectueroperation (
  p_id_compte IN NUMBER, p_type IN VARCHAR2, p_montant IN NUMBER
) IS
  v_nb NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_nb FROM compte WHERE id_compte = p_id_compte;
  IF v_nb = 0 THEN
    RAISE_APPLICATION_ERROR(-20301, 'Compte inconnu');
  END IF;
  INSERT INTO operation (id_operation, id_compte, type_op, montant)
  VALUES ((SELECT NVL(MAX(id_operation), 0) + 1 FROM operation), p_id_compte, UPPER(p_type), p_montant);
END effectueroperation;
/
- Pas de COMMIT : l'appelant valide. Le solde est géré par le trigger de la question suivante.

CREATE OR REPLACE TRIGGER trg_operation_solde
BEFORE INSERT ON operation
FOR EACH ROW
DECLARE
  v_solde compte.solde%TYPE;
BEGIN
  SELECT solde INTO v_solde FROM compte WHERE id_compte = :NEW.id_compte;

  IF :NEW.type_op = 'RETRAIT' THEN
    IF v_solde < :NEW.montant THEN
      RAISE_APPLICATION_ERROR(-20302, 'Solde insuffisant');
    END IF;
    UPDATE compte SET solde = solde - :NEW.montant WHERE id_compte = :NEW.id_compte;
  ELSE
    UPDATE compte SET solde = solde + :NEW.montant WHERE id_compte = :NEW.id_compte;
  END IF;
END;
/
- La table lue et modifiée (compte) n'est pas la table du trigger (operation) : pas de table en mutation.
- BEFORE : la vérification se fait avant l'écriture ; l'échec annule l'insertion de l'opération.
